BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TYPE actor_kind AS ENUM ('human','agent','service');
CREATE TYPE membership_role AS ENUM ('admin','maintainer','member');
CREATE TYPE status_category AS ENUM ('backlog','planned','started','completed','canceled');
CREATE TYPE outbox_status AS ENUM ('pending','delivering','delivered','dead');

CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, revision integer NOT NULL DEFAULT 1 CHECK(revision > 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE actors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, kind actor_kind NOT NULL, email citext, display_name text NOT NULL, password_hash text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,email), CHECK((kind='human' AND email IS NOT NULL AND password_hash IS NOT NULL) OR kind <> 'human'));
CREATE TABLE teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name text NOT NULL, key text NOT NULL, next_work_item_number integer NOT NULL DEFAULT 1 CHECK(next_work_item_number > 0), revision integer NOT NULL DEFAULT 1 CHECK(revision > 0), deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,key));
CREATE TABLE memberships (workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, team_id uuid REFERENCES teams(id) ON DELETE CASCADE, actor_id uuid NOT NULL REFERENCES actors(id) ON DELETE CASCADE, role membership_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(team_id,actor_id));
CREATE TABLE workflow_states (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_id uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE, name text NOT NULL, category status_category NOT NULL, color text NOT NULL DEFAULT '#64748b', position integer NOT NULL DEFAULT 0, is_archived boolean NOT NULL DEFAULT false, revision integer NOT NULL DEFAULT 1 CHECK(revision > 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(team_id,name));
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, team_id uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE, name text NOT NULL, summary text, description text, status text NOT NULL DEFAULT 'planned', lead_actor_id uuid REFERENCES actors(id), target_date date, revision integer NOT NULL DEFAULT 1 CHECK(revision > 0), deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE work_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, team_id uuid NOT NULL REFERENCES teams(id) ON DELETE RESTRICT, number integer NOT NULL CHECK(number > 0), title text NOT NULL, description text, status_id uuid NOT NULL REFERENCES workflow_states(id), priority text NOT NULL DEFAULT 'none' CHECK(priority IN ('none','urgent','high','medium','low')), due_date date, responsible_human_actor_id uuid REFERENCES actors(id), labels text[] NOT NULL DEFAULT '{}', project_id uuid REFERENCES projects(id) ON DELETE SET NULL, revision integer NOT NULL DEFAULT 1 CHECK(revision > 0), deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(team_id,number));
CREATE TABLE channels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, work_item_id uuid NOT NULL UNIQUE REFERENCES work_items(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), channel_id uuid NOT NULL REFERENCES channels(id) ON DELETE CASCADE, author_actor_id uuid NOT NULL REFERENCES actors(id), parent_comment_id uuid REFERENCES comments(id) ON DELETE SET NULL, reply_to_comment_id uuid REFERENCES comments(id) ON DELETE SET NULL, body text NOT NULL, mentions uuid[] NOT NULL DEFAULT '{}', is_resolved boolean NOT NULL DEFAULT false, revision integer NOT NULL DEFAULT 1 CHECK(revision > 0), deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE saved_views (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, owner_actor_id uuid NOT NULL REFERENCES actors(id), team_id uuid REFERENCES teams(id) ON DELETE CASCADE, name text NOT NULL, filters jsonb NOT NULL DEFAULT '{}'::jsonb, layout text NOT NULL CHECK(layout IN ('list','board')), revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL REFERENCES actors(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_idempotency_keys (workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, actor_id uuid NOT NULL REFERENCES actors(id) ON DELETE CASCADE, idempotency_key text NOT NULL, request_hash text NOT NULL, response_status integer, response_body jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,actor_id,idempotency_key));
CREATE TABLE domain_events (cursor bigserial PRIMARY KEY, id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, event_type text NOT NULL, event_version integer NOT NULL DEFAULT 1, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, aggregate_revision integer, actor_id uuid NOT NULL REFERENCES actors(id), correlation_id text NOT NULL, idempotency_key text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), domain_event_id uuid NOT NULL UNIQUE REFERENCES domain_events(id) ON DELETE CASCADE, topic text NOT NULL, partition_key text NOT NULL, status outbox_status NOT NULL DEFAULT 'pending', attempt_count integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, locked_by text, delivered_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX work_items_active_team_status ON work_items(team_id,status_id) WHERE deleted_at IS NULL;
CREATE INDEX work_items_search_trgm ON work_items USING gin(title gin_trgm_ops);
CREATE INDEX work_items_search_fts ON work_items USING gin(to_tsvector('simple', coalesce(title,'') || ' ' || coalesce(description,'')));
CREATE INDEX comments_search_fts ON comments USING gin(to_tsvector('simple', body));
CREATE INDEX domain_events_workspace_cursor ON domain_events(workspace_id,cursor);
CREATE INDEX outbox_claim ON outbox_events(available_at,created_at) WHERE status IN ('pending','delivering');
COMMIT;
